/** Normal browser download of generated bytes. */
export function downloadBlob(data: BlobPart, filename: string, type: string) {
    const url = URL.createObjectURL(new Blob([data], { type }));
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.rel = 'noopener';
    document.body.append(a);
    a.click();
    a.remove();
    // Give the browser a tick to start the download before revoking.
    setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

export const downloadPdf = (bytes: Uint8Array, filename: string) =>
    downloadBlob(bytes as BlobPart, filename, 'application/pdf');
export const downloadCsv = (text: string, filename: string) => downloadBlob(text, filename, 'text/csv;charset=utf-8');

/** Filename-safe version of a campaign name. */
export const slugify = (text: string) =>
    text
        .normalize('NFD')
        .replace(/[̀-ͯ]/g, '')
        .replace(/[^\w-]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .toLowerCase();
